"""Run the Phase 3 scenarios and write docs/11-phase3-evidence.md from real outputs. MUT_OUT=<file> embeds an existing mutation sweep."""
import io, json, os, pathlib, subprocess, sys, time, warnings, contextlib
ROOT = pathlib.Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "src")); sys.path.insert(0, str(ROOT / "tests")); warnings.simplefilter("ignore")
from rig3 import *
from halvard import cli
from halvard.signet import posture
from halvard.signet.idp import AuthError
from halvard.relay.actions import ActionRequest, Principal
from halvard.relay import commands

out = []
H = lambda t: out.append(f"\n## {t}\n"); P = lambda t="": out.append(t)
def code(t): out.append("```\n" + str(t).rstrip() + "\n```")
env = dict(os.environ, PYTHONWARNINGS="ignore")
P("# Phase 3 evidence\n")
P(f"Generated by `tools/run_acceptance_p3.py` on {time.strftime('%Y-%m-%d %H:%M UTC', time.gmtime())}. Every output below is from that run. "
  "The identity provider and directory are **reference models written by the same author as the detectors**; passing against them proves internal consistency, not behavior on Entra, Okta or a real domain. Read **Not demonstrated**.")
t = subprocess.run([sys.executable, "-W", "ignore", "-m", "unittest", "discover", "-s", "tests"], cwd=ROOT, capture_output=True, text=True, env=env)
H("Test suite"); code("\n".join(t.stderr.strip().splitlines()[-4:]))
mo = os.environ.get("MUT_OUT"); mtxt = pathlib.Path(mo).read_text(encoding="utf-8") if mo and pathlib.Path(mo).exists() else subprocess.run([sys.executable, "tools/mutation_check.py"], cwd=ROOT, capture_output=True, text=True, env=env).stdout
H("Do the tests bite? (full sweep, throwaway copies)"); code(mtxt); P(f"Killed: {mtxt.count('KILLED')}; survived or skipped: {mtxt.count('SURVIVED') + mtxt.count('SKIP')}.")

H("C1. A stolen session cannot keep acting after containment (the acceptance case)")
buf = io.StringIO()
with contextlib.redirect_stdout(buf): cli.stolen_session()
code(buf.getvalue())
P("The attacker's attempts are real calls against the reference IdP and resource servers, not printed claims. The Team Wiki row is the honest residual: that application does not recheck tokens, so the one already issued works until it expires. The case page says so and for how long.")

H("C2. Offline laptop: identity side does not wait, device step queues, expired commands are dropped")
w = World().alice_signs_in(); w.stealer_runs(); w.attacker_replays(); w.agent.set_online(False); w.cp.process(); c = next(iter(w.cp.cases.cases.values())); L = []
try: w.cp.idp.refresh_grant(w.stolen["refresh_token"], "203.0.113.7", MOW); L.append("stolen refresh: STILL WORKS")
except AuthError as e: L.append(f"stolen refresh while the laptop is offline: refused ({e.reason}), the identity side did not wait")
L.append(f"laptop isolated yet: {w.host.isolated}; case status: {c.status}; waiting: {[p for p in c.pending if 'isolate_host' in p]}")
L.append(f"laptop reconnects within the command's lifetime: {[ (o['action'], o['status']) for o in w.cp.fleet.reconnect('LT-17')]}; isolated now: {w.host.isolated}")
w2 = World().alice_signs_in(); w2.stealer_runs(); w2.attacker_replays(); w2.agent.set_online(False); w2.cp.process(); w2.clock.advance(7 * 3600)
o = w2.cp.fleet.reconnect("LT-17")[0]; L.append(f"a second laptop reconnects after 7 hours: {o['status']} ({o['message']}); isolated: {w2.host.isolated}")
code("\n".join(L))

H("C3. A hijacked Domain Admin needs two people; a standard user's containment does not")
w = World().alice_signs_in(); bob = w.cp.idp.sign_in("bob@acme.com", "correct-horse", "198.51.100.9", LON, mfa="approve", prompts=7); w.cp.idp.refresh_grant(bob["refresh_token"], "203.0.113.7", MOW); w.cp.signet.sync_graph(); w.cp.process()
c = [c for c in w.cp.cases.cases.values() if any("bob" in f.entity_id for f in c.findings)][0]; pend = next(iter(w.cp.engine.pending)); r1 = w.cp.engine.pending[pend]
L = [f"class of Bob's account: {w.cp.class_of('id:idp:bob@acme.com')}; automatic attempt -> {w.cp.auto_log[-1][1]}; rule {r1['reqmt'].level}", f"preview: {r1['plan']['summary'][:190]}..."]
L.append(f"requester-style approval by the same person twice: {w.cp.approve(pend, ADM1:=Principal('u-adm1','it_admin'), c).status} then {w.cp.approve(pend, ADM1, c).status}")
L.append(f"second administrator: {w.cp.approve(pend, Principal('u-adm2','it_admin'), c).status}; case {c.status}")
try: w.cp.idp.refresh_grant(bob["refresh_token"], "203.0.113.7", MOW); L.append("Bob's stolen refresh: STILL WORKS")
except AuthError as e: L.append(f"Bob's stolen refresh: refused ({e.reason})")
code("\n".join(L))

H("C4. The device defends itself: a control plane cannot talk it into less than its own rules")
w = World(device_class="clinical"); L = []
good_one = commands.sign(POLICY_KEY, device="LT-17", action="isolate_host", params={}, reason="r", case="c", approvals=[{"id": "u1", "role": "it_admin"}], rule="two_person", issuer="cp", now=w.clock.now())
L.append("clinical device, command with 1 approver claiming two_person: " + w.agent.execute_command(good_one, POLICY_KEY)["message"])
low = commands.sign(POLICY_KEY, device="LT-17", action="isolate_host", params={}, reason="r", case="c", approvals=[], rule="notify", issuer="cp", now=w.clock.now()); L.append("command claiming 'notify': " + w.agent.execute_command(low, POLICY_KEY)["message"])
forged = dict(low, action="stop_process"); L.append("tampered after signing: " + w.agent.execute_command(forged, POLICY_KEY)["message"])
unsafe = commands.sign(POLICY_KEY, device="LT-17", action="remote_command", params={"command": "x"}, reason="r", case="c", approvals=[], rule="approve", issuer="cp", now=w.clock.now()); L.append("remote_command over the channel: " + w.agent.execute_command(unsafe, POLICY_KEY)["message"])
two = commands.sign(POLICY_KEY, device="LT-17", action="isolate_host", params={}, reason="r", case="c", approvals=[{"id": "u1", "role": "it_admin"}, {"id": "u2", "role": "analyst"}], rule="two_person", issuer="cp", now=w.clock.now()); L.append("two different approvers: " + w.agent.execute_command(two, POLICY_KEY)["status"] + f" (isolated={w.host.isolated}); replay of the same command: " + w.agent.execute_command(two, POLICY_KEY)["message"])
code("\n".join(L))

H("C5. Detections: what fires, and what stays quiet")
from test_signet_detect import Rig, LON as L0, NYC, MOW as M0, GOOD
rows = []
r = Rig(); r.idp.register_device("D", "alice@acme.com"); t0 = r.idp.sign_in("alice@acme.com", GOOD, "198.51.100.4", L0, device_id="D", mfa="approve", prompts=7); r.clock.advance(300); r.idp.refresh_grant(t0["refresh_token"], "203.0.113.7", M0)
r.idp.grant_consent("bob@acme.com", "evil", ["Mail.Read"]); r.idp.assign_role("carol@acme.com", "Global Administrator", "carol@acme.com"); r.ad.replicate("x", "h", "1.1.1.1"); r.ad.tgt_request("q", "1.1.1.1", 0)
for i in range(6): r.ad.tgs_request("k", f"s{i}", 0x17, "1.1.1.1")
r.ad.add_member("z", "Domain Admins", "z")
for f in r.pump(): rows.append(f"FIRES  {f.detector:22} {f.technique:10} conf {f.confidence:.2f}  {f.why[:95]}")
q = Rig()
for i in range(30): q.ad.tgs_request("jdoe", f"cifs/fs{i%3}", 0x12, "10.0.0.5")
q.idp.sign_in("alice@acme.com", GOOD, "198.51.100.4", L0, mfa="approve", prompts=2)
rows.append(f"QUIET  ordinary AES ticket traffic, one forgotten MFA approval: findings = {len(q.pump())}")
code("\n".join(rows)); P("Thresholds are untuned constants. No detection rate or false-positive rate is claimed. Confidence is rule-assigned, with its reason on every finding.")

H("C6. Hygiene: access paths, standing privilege, service accounts, leavers")
w = World(); cp = w.cp; cp.idp.assign_role("maria@acme.com", "Exchange Administrator", "admin-ops", mode="permanent"); cp.ad.add_user("svc-sql", is_service=True, spns=["MSSQLSvc/db"]); cp.ad.add_member("admin-ops", "Domain Admins", "svc-sql"); cp.ad.logon("svc-sql", True, "10.0.0.5", "SQL1", logon_type=10)
w.clock.advance(60 * 86400); cp.hr.records["p:bob"].status = "terminated"; cp.signet.sync_graph(); L = ["access paths for alice's cloud account: " + str(cp.signet.access_paths("id:idp:alice@acme.com")[:1])]
L += ["standing/unused privilege: " + r.summary for r in posture.standing_privilege(cp.idp, cp.ad)][:4]
inv = posture.service_account_inventory(cp.idp, cp.ad); L.append(f"service account {inv[0]['name']} risks: {inv[0]['risks']}")
L += ["leaver: " + r.summary for r in posture.joiner_mover_leaver(cp.idp, cp.ad, cp.hr)][:3]; code("\n".join(L))

H("C7. Notifying the manager")
w = World().alice_signs_in(); w.stealer_runs(); w.attacker_replays(); w.cp.process(); code(f"sent to {w.ch[0].sent[0][0]} via approved channel:\n{w.ch[0].sent[0][1]}")
ch = Channel("email", owner_identity_of=lambda a: "alice@acme.com"); r = World(channels=[ch]).cp.notifier.notify_manager("p:alice", ["alice@acme.com"]); P(f"A channel owned by an affected account is never used: {r['status']} - {r['message']}")

H("Not demonstrated (so not claimed)")
for x in ("Real Entra/Okta/Google or real Active Directory. The reference models define the contract and enforce tokens, rotation, revocation, compliance and tickets, but they are not those products. Real connectors, their credentials (T31), feed authenticity (T26) and rate limits are unbuilt.",
          "Detection quality on real traffic. Thresholds are untuned; there are no measured detection or false-positive rates and no public test report.",
          "Continuous access evaluation, token lifetimes and token binding behave here as modelled; each real application and IdP must be checked for what it actually does after revocation.",
          "A polling scheduler: `process()` and `connector_health()` are called by tests. The 'within the promised interval' coverage latency for connectors is not demonstrated.",
          "Kerberos ticket lifetime and krbtgt rotation are described and refused-by-design, not exercised against a domain.",
          "Courier (mailed-attachment merge), Keeper approvers, console, installer, asymmetric signing and key management remain unbuilt, as do F057 decoys and F059 session recording.",
          "Case scoring is a documented heuristic; it has not been calibrated against real incidents.")  :
    P("- " + x)
(ROOT / "docs" / "11-phase3-evidence.md").write_text("\n".join(out) + "\n", encoding="utf-8"); print("wrote docs/11-phase3-evidence.md; suite:", "OK" if t.returncode == 0 else "FAILED")
